add_filter( 'woocommerce_login_redirect', 'perfectpixel_login_redirect', 20 );

function perfectpixel_login_redirect( $redirect ) {
	$target = trim( '{{login_redirect_url}}' );
	// Keep explicit redirects (e.g. ?redirect_to= or from the checkout).
	if ( '' === $target || ! empty( $_POST['redirect'] ) ) {
		return $redirect;
	}
	return wp_validate_redirect( 0 === strpos( $target, '/' ) ? home_url( $target ) : $target, $redirect );
}
